#include <unistd.h>
#include <cstdio>

int main() {
    int p[2];

    if (pipe(p) < 0) {
        std::perror("pipe");
        return 1;
    }

    std::printf("read_fd=%d write_fd=%d\n", p[0], p[1]);

    int result = 0;
    if (close(p[0]) < 0) {
        std::perror("close read end");
        result = 1;
    }
    if (close(p[1]) < 0) {
        std::perror("close write end");
        result = 1;
    }

    return result;
}
